// Explicit legacy fixtures for regression tests only. Never imported by the application.
import {createOperationalStore} from '../../../interno/operational-store.js';
const remote=createOperationalStore('hortifruti_receipts');
export const loadHortifruti=()=>false?remote.load():Promise.resolve([]);
import {safeOrderSnapshot} from './hortifruti-safe-snapshot.js';
import {batchPricingItems} from '../../../interno/hortifruti/pricing-batch.js';
import {normalizeTemplate} from '../legacy-catalogs/modelos-cartaz/model.js';
import {normalizeSearch} from '../../../shared/filters.js';
import {calculateLine,validDate,assertComplete,formatDecimal} from './hortifruti-model.js';
const clone=value=>structuredClone(value);
export function createHortifrutiRepository(){let records=[];
 const get=id=>{const r=records.find(r=>r.id===id);if(!r)throw new Error('Compra não encontrada.');return r;};
 const event=(r,action,responsible='')=>r.history.push({id:crypto.randomUUID(),action,responsible:String(responsible||'').trim(),at:new Date().toISOString()});
 const normalize=(input,{partners,products,units})=>{const partner=partners.find(p=>p.id===input.partnerId);if(!partner)throw new Error('Selecione um parceiro cadastrado.');if(!validDate(input.date))throw new Error('Informe uma data válida.');if(input.items!==undefined&&!Array.isArray(input.items))throw new Error('Lista de produtos inválida.');const seen=new Set();const items=(input.items||[]).map(item=>{const product=products.find(p=>p.id===item.productId);if(!product)throw new Error('Selecione produtos cadastrados.');if(seen.has(product.id))throw new Error('Produto repetido: ajuste a quantidade na mesma linha.');seen.add(product.id);const unit=units.find(u=>u.id===(item.unit||product.unit));if(!unit||unit.symbol.toUpperCase()!=='KG')throw new Error('A pesagem deve ser informada em kg.');return {productId:product.id,name:product.name,code:String(product.code??'').trim(),photo:product.photo||'',unit:unit.id,unitSymbol:unit.symbol,purchaseUnit:product.unit,...calculateLine(item)};});return {partner:{id:partner.id,name:partner.name},date:input.date,notes:String(input.notes||'').trim(),items};};
 return {list({query='',status='pending',start='',end=''}={}){if(start&&!validDate(start)||end&&!validDate(end)||start&&end&&start>end)throw new Error('Verifique o intervalo de datas.');const needle=normalizeSearch(query);return records.filter(r=>(!status||r.status===status)&&(!start||r.date>=start)&&(!end||r.date<=end)&&(!needle||normalizeSearch([r.partner.name,r.notes,...r.items.map(i=>i.name)].join(' ')).includes(needle))).map(clone);},get(id){return clone(get(id));},
 create(input,catalog){const data=normalize(input,catalog);const r={id:crypto.randomUUID(),...data,status:'pending',weighed:false,entryConfirmed:false,history:[]};event(r,'Compra registrada',input.responsible);records.unshift(r);return clone(r);},
 update(id,input,catalog){const r=get(id);if(r.status==='finished')throw new Error('Compra finalizada não pode ser alterada.');const data=normalize(input,catalog);data.items=data.items.map(item=>({...item,code:r.items.find(old=>old.productId===item.productId)?.code??'',pricing:clone(r.items.find(old=>old.productId===item.productId)?.pricing||{salePriceCents:null,templateSnapshot:null,posterQuantity:1,printLayout:'individual'})}));const changed=JSON.stringify(r.items.map(({pricing,...item})=>item))!==JSON.stringify(data.items.map(({pricing,...item})=>item))||r.partner.id!==data.partner.id||r.date!==data.date;const weightFields=item=>({productId:item.productId,quantityMicros:item.quantityMicros,weighMode:item.weighMode,boxes:item.boxes,previousWeightMicros:item.previousWeightMicros});const weightChanged=r.partner.id!==data.partner.id||r.date!==data.date||JSON.stringify(r.items.map(weightFields))!==JSON.stringify(data.items.map(weightFields));const corrections=changed?data.items.map(item=>{const old=r.items.find(i=>i.productId===item.productId);return `${item.name}: ${old?formatDecimal(old.quantityMicros)||'a pesar':'novo'} → ${formatDecimal(item.quantityMicros)||'a pesar'} kg; ${(item.boxes||[]).length} caixa(s)`;}).join('; '):'';Object.assign(r,data);if(changed){if(weightChanged)r.weighed=false;r.entryConfirmed=false;event(r,`Compra atualizada. ${corrections}`,input.responsible);}else event(r,'Dados da compra salvos',input.responsible);return clone(r);},
 addProducts(id,productIds,catalog){const r=get(id);if(r.status==='finished')throw new Error('Pedido finalizado não pode ser alterado.');if(!Array.isArray(productIds)||!productIds.length)throw new Error('Selecione pelo menos um produto de Hortifruti.');const kg=catalog.units.find(u=>u.symbol.toUpperCase()==='KG');if(!kg)throw new Error('Cadastre a unidade KG antes de adicionar produtos.');const unique=[...new Set(productIds)];const added=unique.map(productId=>{const product=catalog.products.find(p=>p.id===productId);if(!product||normalizeSearch(product.category)!=='hortifruti')throw new Error('Selecione somente produtos da categoria Hortifruti.');if(r.items.some(i=>i.productId===productId))throw new Error('Este produto já está no pedido.');return {productId:product.id,name:product.name,code:String(product.code??'').trim(),photo:product.photo||'',unit:kg.id,unitSymbol:'KG',purchaseUnit:product.unit,...calculateLine({}),pricing:{salePriceCents:null,templateSnapshot:null,posterQuantity:1,printLayout:'individual'}};});r.items.push(...added);r.weighed=false;r.entryConfirmed=false;event(r,`${added.length} produto(s) selecionado(s) para compra`);return clone(r);},
 removeProduct(id,productId){const r=get(id);if(r.status==='finished')throw new Error('Compra finalizada não permite remover produtos.');const index=r.items.findIndex(item=>item.productId===productId);if(index<0)throw new Error('Produto não encontrado no pedido.');const [removed]=r.items.splice(index,1);r.weighed=false;r.entryConfirmed=false;event(r,`Produto removido do pedido: ${removed.name}`);return clone(r);},
 autosave(id,input,catalog){const r=get(id);if(r.status==='finished')throw new Error('Reabra a compra para ajustar os dados.');const {snapshot,errors}=safeOrderSnapshot(r,input,catalog.partners);const materialBefore=JSON.stringify({partner:r.partner,date:r.date,items:r.items});const before=JSON.stringify({partner:r.partner,date:r.date,notes:r.notes,items:r.items});if(snapshot.partner.id)r.partner=snapshot.partner;if(snapshot.date)r.date=snapshot.date;r.notes=snapshot.notes;r.items=snapshot.items;if(before!==JSON.stringify({partner:r.partner,date:r.date,notes:r.notes,items:r.items})){if(materialBefore!==JSON.stringify({partner:r.partner,date:r.date,items:r.items})){r.weighed=false;r.entryConfirmed=false;}event(r,'Alterações do pedido salvas automaticamente',input.responsible);}return {record:clone(r),errors};},
 setPricingBatch(id,productIds,patch){const r=get(id);const updated=batchPricingItems(r.items,productIds,patch);r.items=updated;event(r,`Configuração de cartazes aplicada em lote a ${new Set(productIds).size} produto(s)`);return clone(r);},
 setPrintPeriod(id,{start,end}){const r=get(id);if((!!start)!=(!!end)||start&&!validDate(start)||end&&!validDate(end)||start&&end&&start>end)throw new Error('Preencha as duas datas da validade ou deixe ambas em branco.');const period={start:String(start||''),end:String(end||'')};if(JSON.stringify(period)!==JSON.stringify(r.posterPeriod)){r.posterPeriod=period;event(r,'Validade dos cartazes atualizada');}return clone(r);},
 setPricing(id,productId,patch){const r=get(id);const item=r.items.find(i=>i.productId===productId);if(!item)throw new Error('Produto não encontrado no pedido.');const old=item.pricing||{salePriceCents:null,templateSnapshot:null,posterQuantity:1,printLayout:'individual'};const next={...clone(old),...clone(patch)};if(next.salePriceCents!==null&&(!Number.isSafeInteger(next.salePriceCents)||next.salePriceCents<=0||next.salePriceCents>999999))throw new Error('Informe preço de venda entre R$ 0,01 e R$ 9.999,99.');if(!Number.isInteger(next.posterQuantity)||next.posterQuantity<1||next.posterQuantity>100)throw new Error('Use de 1 a 100 cartazes por produto.');if(!['individual','two-a4'].includes(next.printLayout))throw new Error('Escolha a organização de impressão.');if(next.templateSnapshot)next.templateSnapshot=normalizeTemplate(next.templateSnapshot);if(JSON.stringify(old)!==JSON.stringify(next)){item.pricing=next;event(r,`Precificação de ${item.name} salva`);}return clone(r);},
 finalize(id,{confirmed=false,responsible=''}={}){const r=get(id);if(!confirmed)throw new Error('Confirme a finalização da compra.');if(r.status==='finished')throw new Error('Compra já finalizada.');const missing=r.items.filter(i=>!i.quantityMicros||i.boxesIncomplete||!i.totalCents||!i.unitMicros).length;r.status='finished';r.completedWithPending=!r.items.length||missing>0;event(r,r.completedWithPending?`Compra finalizada com dados pendentes (${missing} produto(s) a completar)`:'Compra finalizada',responsible);return clone(r);},
 reopen(id,{confirmed=false,responsible=''}={}){const r=get(id);if(!confirmed)throw new Error('Confirme a reabertura da compra.');if(r.status!=='finished')throw new Error('A compra já está aberta.');r.status='pending';r.completedWithPending=false;event(r,'Compra reaberta para ajustes',responsible);return clone(r);},
 advance(id,stage,responsible=''){const r=get(id);if(r.status==='finished')throw new Error('Compra já finalizada.');if(stage==='weighed'){if(!r.items.length||r.items.some(i=>!i.quantityMicros||i.boxesIncomplete))throw new Error('Informe o peso líquido de todos os produtos antes de confirmar a pesagem.');if(r.weighed)throw new Error('Pesagem já confirmada.');r.weighed=true;event(r,'Pesagem líquida conferida',responsible);}else if(stage==='entry'){assertComplete(r);if(!r.weighed)throw new Error('Confirme a pesagem antes de registrar a entrada.');if(r.entryConfirmed)throw new Error('Entrada já confirmada.');r.entryConfirmed=true;event(r,'Entrada confirmada',responsible);}else if(stage==='finished'){assertComplete(r);if(!r.weighed||!r.entryConfirmed)throw new Error('Confirme a pesagem e a entrada antes de finalizar.');r.status='finished';event(r,'Compra finalizada',responsible);}else throw new Error('Etapa inválida.');return clone(r);},reset(){records=[];}};
}
const localHortifruti=createHortifrutiRepository();
const cleanRemoteInput=input=>({...input,...(Array.isArray(input.items)?{items:input.items.map(({_computed,...item})=>item)}:{})});
const remoteHortifruti={
 list({query='',status='pending',start='',end=''}={}){const needle=normalizeSearch(query);return remote.list().filter(r=>(!status||r.status===status)&&(!start||r.date>=start)&&(!end||r.date<=end)&&(!needle||normalizeSearch([r.partner.name,r.notes,...r.items.map(i=>i.name)].join(' ')).includes(needle)));},
 get:id=>remote.get(id),
 create:input=>remote.run('create',null,cleanRemoteInput(input)),
 update:(id,input)=>remote.run('update',id,cleanRemoteInput(input)),
 addProducts:(id,productIds)=>remote.run('addProducts',id,{productIds}),
 removeProduct:(id,productId)=>remote.run('removeProduct',id,{productId}),
 async autosave(id,input){const response=await remote.run('autosave',id,cleanRemoteInput(input));return response.record?response:{record:response,errors:response._errors||[]};},
 setPricingBatch:(id,productIds,patch)=>remote.run('setPricingBatch',id,{productIds,patch}),
 setPrintPeriod:(id,input)=>remote.run('setPrintPeriod',id,input),
 setPricing:(id,productId,patch)=>remote.run('setPricing',id,{productId,patch}),
 finalize:(id,input)=>remote.run('finalize',id,input),
 reopen:(id,input)=>remote.run('reopen',id,input),
 advance:(id,stage,responsible)=>remote.run('advance',id,{stage,responsible}),
 reset:()=>remote.reset()
};
export const hortifrutiRepository=new Proxy({}, {get:(_,key)=>(false?remoteHortifruti:localHortifruti)[key]});
